from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


@proc
def kernel_adi_base(
    tsteps: size,
    n: size,
    mul1: DATA_TYPE,
    mul2: DATA_TYPE,
    u: DATA_TYPE[n, n] @ DRAM,
    v: DATA_TYPE[n, n] @ DRAM,
    p: DATA_TYPE[n, n] @ DRAM,
    q: DATA_TYPE[n, n] @ DRAM,
):
    # ADI scheme on an n x n grid for tsteps time steps.
    #
    # u: solution grid (updated in-place each time step)
    # v: temporary grid used for the intermediate half-step
    # p, q: workspace for the tridiagonal solves
    #
    # The computation only touches the interior [1:n-1) x [1:n-1),
    # but we still require at least a 3x3 grid to make the stencils valid.
    assert n > 2

    a: DATA_TYPE
    b: DATA_TYPE
    c: DATA_TYPE
    d: DATA_TYPE
    e: DATA_TYPE
    f: DATA_TYPE

    # Precompute scalar coefficients once.
    a = -mul1 / 2.0
    b = 1.0 + mul1
    c = a
    d = -mul2 / 2.0
    e = 1.0 + mul2
    f = d

    for t in seq(1, tsteps + 1):
        # --------------------------------------------------------------
        # Column sweep: solve independent tridiagonal systems along
        # each column of u, writing the result into v.
        # --------------------------------------------------------------
        for i in seq(1, n - 1):
            # Forward sweep initialization for column i.
            v[0, i] = 1.0
            p[i, 0] = 0.0
            q[i, 0] = v[0, i]

            # Forward sweep along the column.
            #
            # This matches the reference PolyBench implementation:
            # - dependency only along j (p[i, j-1], q[i, j-1])
            # - reads a 3-point vertical stencil from u at (j, i-1/i/i+1)
            for j in seq(1, n - 1):
                p[i, j] = -c / (a * p[i, j - 1] + b)
                q[i, j] = (
                    -d * u[j, i - 1]
                    + (1.0 + 2.0 * d) * u[j, i]
                    - f * u[j, i + 1]
                    - a * q[i, j - 1]
                ) / (a * p[i, j - 1] + b)

            # Backward substitution for column i.
            v[n - 1, i] = 1.0
            for j in seq(1, n - 1):
                v[n - 1 - j, i] = (
                    p[i, n - 1 - j] * v[n - j, i]
                    + q[i, n - 1 - j]
                )

        # --------------------------------------------------------------
        # Row sweep: solve independent tridiagonal systems along
        # each row of v, overwriting u with the new solution.
        # --------------------------------------------------------------
        for i in seq(1, n - 1):
            # Forward sweep initialization for row i.
            u[i, 0] = 1.0
            p[i, 0] = 0.0
            q[i, 0] = u[i, 0]

            # Forward sweep along the row.
            #
            # Again, dependencies are only along j; v is read-only
            # in this phase, while u and (p, q) are written.
            for j in seq(1, n - 1):
                p[i, j] = -f / (d * p[i, j - 1] + e)
                q[i, j] = (
                    -a * v[i - 1, j]
                    + (1.0 + 2.0 * a) * v[i, j]
                    - c * v[i + 1, j]
                    - d * q[i, j - 1]
                ) / (d * p[i, j - 1] + e)

            # Backward substitution for row i.
            u[i, n - 1] = 1.0
            for j in seq(1, n - 1):
                u[i, n - 1 - j] = (
                    p[i, n - 1 - j] * u[i, n - j]
                    + q[i, n - 1 - j]
                )


# Small scheduling driver that applies performance-oriented
# transformations to kernel_adi_base while preserving semantics.
def schedule_kernel_adi(proc: Procedure) -> Procedure:
    p = proc

    # ----------------------------------------------------------
    # 1. Parallelize the independent per-column and per-row
    #    sweeps.  Within a fixed time step t, each column (in
    #    the column sweep) and each row (in the row sweep) is
    #    completely independent:
    #
    #    - Column sweep:
    #        * p[i, *], q[i, *], v[*, i] and u[*, i-1..i+1]
    #          are only touched for a single i at a time.
    #        * No iteration accesses data for a different i.
    #
    #    - Row sweep:
    #        * u[i, *], p[i, *], q[i, *] are only touched for
    #          a single i; v is read-only and shared.
    #
    #    Thus these loops can be safely parallelized.
    # ----------------------------------------------------------
    col_i = p.find_loop("i")        # first i-loop: column sweep
    p = parallelize_loop(p, col_i)

    row_i = p.find_loop("i #1")     # second i-loop: row sweep
    p = parallelize_loop(p, row_i)

    # ----------------------------------------------------------
    # 2. Simplify any algebraic redundancies that may have been
    #    introduced by the transformations above.
    # ----------------------------------------------------------
    p = simplify(p)

    # ----------------------------------------------------------
    # 3. Expose the optimized version under the name expected
    #    by the C driver and generated header.
    # ----------------------------------------------------------
    p = rename(p, "kernel_adi")
    return p


# This is the procedure that exocc will lower to C.
kernel_adi = schedule_kernel_adi(kernel_adi_base)

