/**
 * Exo ADI driver: mirrors PolyBench/C adi.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "adi.h"

/* Include the Exo-generated kernel header. */
#include "generated/adi/adi.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      {
	u[i][j] =  (DATA_TYPE)(i + n-j) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static 
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n)) 
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("u");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, u[i][j]);
    }
  POLYBENCH_DUMP_END("u");
  POLYBENCH_DUMP_FINISH;
}


/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

#
# Base ADI kernel in Exo. This mirrors the PolyBench/C adi.c kernel.
# The data layout matches the C code: all 2D arrays are row-major
# DATA_TYPE[n, n] buffers in DRAM.
#
@proc
def kernel_adi(
    tsteps: size,
    n: size,
    mul1: DATA_TYPE,
    mul2: DATA_TYPE,
    u: DATA_TYPE[n, n] @ DRAM,
    v: DATA_TYPE[n, n] @ DRAM,
    p: DATA_TYPE[n, n] @ DRAM,
    q: DATA_TYPE[n, n] @ DRAM,
):
    # We access u/v/p/q on interior points [1:n-2] in both dimensions.
    assert n > 2

    a: DATA_TYPE
    b: DATA_TYPE
    c: DATA_TYPE
    d: DATA_TYPE
    e: DATA_TYPE
    f: DATA_TYPE

    # Coefficients are constant over all time steps.
    a = -mul1 / 2.0
    b = 1.0 + mul1
    c = a
    d = -mul2 / 2.0
    e = 1.0 + mul2
    f = d

    for t in seq(1, tsteps + 1):
        # -------------------------------------------------------------
        # Column sweep: for each column i, solve a tridiagonal system
        # along j, writing into v(:, i). The original u is read-only
        # during this phase.
        # -------------------------------------------------------------
        for i in seq(1, n - 1):
            # Dirichlet boundary at the top of the column.
            v[0, i] = 1.0
            p[i, 0] = 0.0
            q[i, 0] = v[0, i]

            # Forward sweep along j.
            for j in seq(1, n - 1):
                # Local denominator for the tridiagonal update.
                denom_col: DATA_TYPE
                denom_col = a * p[i, j - 1] + b

                p[i, j] = -c / denom_col
                q[i, j] = (
                    -d * u[j, i - 1]
                    + (1.0 + 2.0 * d) * u[j, i]
                    - f * u[j, i + 1]
                    - a * q[i, j - 1]
                ) / denom_col

            # Dirichlet boundary at the bottom of the column.
            v[n - 1, i] = 1.0

            # Backward substitution along j.
            for j in seq(1, n - 1):
                v[n - 1 - j, i] = (
                    p[i, n - 1 - j] * v[n - j, i]
                    + q[i, n - 1 - j]
                )

        # -------------------------------------------------------------
        # Row sweep: for each row i, solve a tridiagonal system along j,
        # writing back into u(i, :). This phase reads v but does not
        # modify it.
        # -------------------------------------------------------------
        for i in seq(1, n - 1):
            # Dirichlet boundary at the left side of the row.
            u[i, 0] = 1.0
            p[i, 0] = 0.0
            q[i, 0] = u[i, 0]

            # Forward sweep along j.
            for j in seq(1, n - 1):
                # Local denominator for this tridiagonal system.
                denom_row: DATA_TYPE
                denom_row = d * p[i, j - 1] + e

                p[i, j] = -f / denom_row
                q[i, j] = (
                    -a * v[i - 1, j]
                    + (1.0 + 2.0 * a) * v[i, j]
                    - c * v[i + 1, j]
                    - d * q[i, j - 1]
                ) / denom_row

            # Dirichlet boundary at the right side of the row.
            u[i, n - 1] = 1.0

            # Backward substitution along j.
            for j in seq(1, n - 1):
                u[i, n - 1 - j] = (
                    p[i, n - 1 - j] * u[i, n - j]
                    + q[i, n - 1 - j]
                )

#
# Scheduling
#
# The tridiagonal recurrences along j are inherently sequential, but
# different rows/columns (indexed by i) are independent for a given
# time step t:
#   - In the column sweep, v(:, i), p(i, :), q(i, :) for different i
#     are written independently and only read u, which is not modified
#     in this phase.
#   - In the row sweep, u(i, :), p(i, :), q(i, :) for different i are
#     written independently and only read v, which is not modified in
#     this phase.
#
# Therefore we can safely parallelize both i-loops. Exo will lower
# these to OpenMP parallel-for loops, exploiting the many-core CPU.
#

# Parallelize column-sweep i-loop
col_i = kernel_adi.find_loop("i")
kernel_adi = parallelize_loop(kernel_adi, col_i)

# Parallelize row-sweep i-loop (second 'i' loop in the body)
row_i = kernel_adi.find_loop("i #1")
kernel_adi = parallelize_loop(kernel_adi, row_i)

# Let Exo clean up and slightly simplify expressions after scheduling.
kernel_adi = simplify(kernel_adi)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(u, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(v, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(p, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(q, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(u));

  /* Precompute scalar coefficients used by the Exo kernel. */
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;

  DX = SCALAR_VAL(1.0) / (DATA_TYPE)n;
  DY = SCALAR_VAL(1.0) / (DATA_TYPE)n;
  DT = SCALAR_VAL(1.0) / (DATA_TYPE)tsteps;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_adi(/*ctxt=*/NULL,
             tsteps, n,
             (DATA_TYPE*)&mul1, (DATA_TYPE*)&mul2,
             (DATA_TYPE*)POLYBENCH_ARRAY(u),
             (DATA_TYPE*)POLYBENCH_ARRAY(v),
             (DATA_TYPE*)POLYBENCH_ARRAY(p),
             (DATA_TYPE*)POLYBENCH_ARRAY(q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(u)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(u);
  POLYBENCH_FREE_ARRAY(v);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(q);

  return 0;
}
