EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base unscheduled kernel, kept close to the PolyBench adi.c reference.
@proc
def kernel_adi_base(
    tsteps: size,
    n: size,
    mul1: DATA_TYPE,
    mul2: DATA_TYPE,
    u: DATA_TYPE[n, n] @ DRAM,
    v: DATA_TYPE[n, n] @ DRAM,
    p: DATA_TYPE[n, n] @ DRAM,
    q: DATA_TYPE[n, n] @ DRAM,
):
    # We will access u[*, i-1] and u[*, i+1] and similarly for v,
    # so we require at least a 3x3 interior.
    assert n > 2

    a: DATA_TYPE
    b: DATA_TYPE
    c: DATA_TYPE
    d: DATA_TYPE
    e: DATA_TYPE
    f: DATA_TYPE

    # Coefficients only depend on mul1/mul2 and are reused across time steps.
    a = -mul1 / 2.0
    b = 1.0 + mul1
    c = a
    d = -mul2 / 2.0
    e = 1.0 + mul2
    f = d

    # Time stepping loop.
    for t in seq(1, tsteps + 1):
        # ------------------------------------------------------------------
        # Column sweep: implicit solve along the j-direction for each column i.
        # This phase reads u and writes v, p, q.
        # ------------------------------------------------------------------
        for i in seq(1, n - 1):
            v[0, i] = 1.0
            p[i, 0] = 0.0
            q[i, 0] = v[0, i]

            # Forward sweep (tridiagonal solve) along j.
            # We factor the common denominator expression once per iteration
            # to avoid recomputing a*p[i, j-1] + b; this is algebraically
            # identical to the original formulation.
            for j in seq(1, n - 1):
                denom: DATA_TYPE

                denom = a * p[i, j - 1] + b

                p[i, j] = -c / denom
                q[i, j] = (
                    -d * u[j, i - 1]
                    + (1.0 + 2.0 * d) * u[j, i]
                    - f * u[j, i + 1]
                    - a * q[i, j - 1]
                ) / denom

            v[n - 1, i] = 1.0

            # Backward substitution along j.
            for j in seq(1, n - 1):
                v[n - 1 - j, i] = (
                    p[i, n - 1 - j] * v[n - j, i]
                    + q[i, n - 1 - j]
                )

        # ------------------------------------------------------------------
        # Row sweep: implicit solve along the i-direction for each row i.
        # This phase reads v and writes back into u, p, q.
        # ------------------------------------------------------------------
        for i in seq(1, n - 1):
            u[i, 0] = 1.0
            p[i, 0] = 0.0
            q[i, 0] = u[i, 0]

            # Forward sweep along j.
            for j in seq(1, n - 1):
                denom2: DATA_TYPE

                denom2 = d * p[i, j - 1] + e

                p[i, j] = -f / denom2
                q[i, j] = (
                    -a * v[i - 1, j]
                    + (1.0 + 2.0 * a) * v[i, j]
                    - c * v[i + 1, j]
                    - d * q[i, j - 1]
                ) / denom2

            u[i, n - 1] = 1.0

            # Backward substitution along j.
            for j in seq(1, n - 1):
                u[i, n - 1 - j] = (
                    p[i, n - 1 - j] * u[i, n - j]
                    + q[i, n - 1 - j]
                )


# ----------------------------------------------------------------------
# Scheduling: start from the base kernel and apply performance-oriented
# transforms. The final exported procedure must be named `kernel_adi`.
# ----------------------------------------------------------------------
kernel_adi = rename(kernel_adi_base, "kernel_adi")

# Parallelize the outer i-loops in both column and row sweeps.
# These loops are independent across i: every iteration touches disjoint
# rows/columns of u, v, p, and q, and only reads neighboring data, so
# Exo's dependence analysis will allow OpenMP-style parallelization.
col_i = kernel_adi.find_loop("for i in _:_ #0")
kernel_adi = parallelize_loop(kernel_adi, col_i)

row_i = kernel_adi.find_loop("for i in _:_ #1")
kernel_adi = parallelize_loop(kernel_adi, row_i)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(u, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(v, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(p, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(q, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(u));

  /* Precompute scalar coefficients used by the Exo kernel. */
